#!/bin/sh
# Scaffold for ho-why-retries-ignored: writes the task's files into the current directory.
set -e
printf '# fetch client\n\nSettings live in config.json:\n\n    max_retries   how many times to retry after a connection error (default 3)\n    timeout       seconds before a single request gives up\n\nThe client sleeps a little longer before each retry.\n' > README.md && printf '{"max_retries": 5, "timeout": 10}\n' > config.json && printf '"""Tiny retrying wrapper around a request function."""\nimport json\nimport time\n\nDEFAULT_RETRIES = 2\nBACKOFF_SECONDS = 0.5\n\n\ndef load_config(path="config.json"):\n    with open(path) as f:\n        return json.load(f)\n\n\ndef fetch(do_request, cfg):\n    """Call do_request(), retrying on ConnectionError."""\n    retries = cfg.get("retries", DEFAULT_RETRIES)\n    attempt = 0\n    while True:\n        try:\n            return do_request()\n        except ConnectionError:\n            if attempt >= retries:\n                raise\n            attempt += 1\n            time.sleep(BACKOFF_SECONDS * attempt)\n' > client.py
